"teaser-verify2-003", "stage": "verify2", "claims": 4, "verdict": "VERIFIED", "unproven": 0, "text_sha256": "d7c9f2c08615c2508ab49713b03d60ef2bceabd12a4c163cbe3ff92110a5eaa3"}, "ai_system": "Claude (Anthropic) and MiniMax M3.1 Flash (MiniMax): anthropic/claude-opus-5-5, anthropic/claude-sonnet-5-5, minimax/MiniMax-M3.1-Flash-Preview, an-sites-remediation-2026-09", "web_facts": [], "desc_sha256": "438ce4cc758d9f99d40d87a85586930642ae43e8749cabfefb275053298ddcb9", "text_sha256": "d7c9f2c08615c2508ab49713b03d60ef2bceabd12a4c163cbe3ff92110a5eaa3"}, "_description_check": {"v": 2, "of": 4, "run": "mass-2026-09-27-02", "kept": 2, "checker": "Claude (Anthropic) and MiniMax M3.1 Flash (MiniMax): anthropic/claude-opus-5-5, anthropic/claude-sonnet-5-5, minimax/MiniMax-M3.1-Flash-Preview, an-sites-remediation-2026-09", "trimmed": 1, "sentences": [{"n": 1, "cites": [1, 2], "reason": null, "verdict": "KEEP", "quote_sha256": ["a7cbf3d948b556380205971fbf2a0916bafbfe762a820c160a299b5d560b876f", "716782fee251d7a5e20cf65ccaa4e8e83f6cef6d375e17c15a0b81b21330d9f4", "364564045fe907beee01da1f270ef9bab7350bf1c632676effff6b834eae517d"]}, {"n": 2, "cites": [], "reason": "unsupported", "verdict": "DROP", "quote_sha256": []}, {"n": 3, "cites": [], "reason": "unsupported", "verdict": "DROP", "quote_sha256": []}, {"n": 4, "cites": [1, 3], "reason": null, "verdict": "KEEP_TRIMMED", "quote_sha256": ["406dcdd699b396c5f0f0f215ea979fc98f4adf6d8a53385dc42157531193b42a", "7f035e864a1d60c34447b0ac033a3e47701e3140f5ec5b188fec450c43457aaf"]}], "verifiers": ["opus-wc-verify-0034"], "desc_sha256": "438ce4cc758d9f99d40d87a85586930642ae43e8749cabfefb275053298ddcb9", "checked_sha256": "cd55f5d1d8dd2b227b2d785d3a7f2e30d050ab0c4036362ab94e3e071f0ac1ee", "verified_sha256": "438ce4cc758d9f99d40d87a85586930642ae43e8749cabfefb275053298ddcb9"}, "description_citations": [{"n": 1, "url": "https://en.wikipedia.org/wiki/Merheleva_Ridge", "title": "Merheleva Ridge", "domain": "en.wikipedia.org"}, {"n": 2, "url": "https://archive.archaeology.org/0701/trenches/fact.html", "title": "Fact Check: Ukrainian \\"Pyramid\\"", "domain": "archive.archaeology.org"}, {"n": 3, "url": "http://news.bbc.co.uk/1/hi/world/europe/5322894.stm", "title": "\''Pyramids\'' discovered in Ukraine", "domain": "news.bbc.co.uk"}], "_description_provenance": {"v": 1, "ai": "generated", "lane": "L", "basis": "description differs from pre-March snapshot d4526691 (plan section 15.3)", "ai_system": "2026-03 enrichment chain (LLM; model per site not recorded)", "desc_sha256": "438ce4cc758d9f99d40d87a85586930642ae43e8749cabfefb275053298ddcb9"}}'' restored on Merheleva Ridge', '438ce4cc758d9f99d40d87a85586930642ae43e8749cabfefb275053298ddcb9', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-adversarial-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The card states as fact that Merheleva Ridge is an Eneolithic temple complex, but reputable sources disagree: the excavator Viktor Klochko dated it from about 4000 BC and called it a temple-and-burial complex (Archaeology magazine, https://archive.archaeology.org/0701/trenches/fact.html), while the Ukrainian Wikipedia calls it ''археологічна пам''ятка бронзової доби'' (https://uk.wikipedia.org/wiki/Мергелева_гряда_(археологічна_пам''ятка)) and the Russian Wikipedia records burials of the Catacomb and Srubna cultures (''Погребения донецкой катакомбной и срубной культуры'') and the verdict of Luhansk geologists and archaeologists at a 2007 conference that ''кроме обычных и самых рядовых курганов для Донбасса, на «Мергелевой гряде» других искусственных сооружений нет'', with the 2007 debate in the journal Arkheolohiia (Gershkovych and Sanzharov) finding ''никаких явных доказательств искусственного происхождения «стен», «дорог» и «платформ» на Мергелевой гряде нет'' (https://ru.wikipedia.org/wiki/Мергелевая_гряда); the card must hedge the temple identification and the Eneolithic date as the excavators'' interpretation, or drop them."}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 54;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_prov_plan p LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_prov_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'raw_data' THEN p.new_value::jsonb IS NOT DISTINCT FROM p.old_value::jsonb OR p.old_value IS NULL
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_prov_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'raw_data' THEN u.raw_data IS DISTINCT FROM p.old_value::jsonb
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_prov_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_prov_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'unified_sites', r.column_name, 'id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/card-provenance', 'wb-teaser-prov-s039-rollback', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card provenance: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_prov_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'raw_data' THEN u.raw_data IS DISTINCT FROM p.new_value::jsonb
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_prov_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'unified_sites'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-prov-s039-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-prov-s039-rollback'
       AND (l.table_name <> 'unified_sites' OR l.column_name NOT IN ('raw_data'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: this run stamp journalled % row(s) outside unified_sites.(raw_data)', bad;
    END IF;

    RAISE NOTICE 'teaser card provenance: % of % planned cell(s) changed and journalled over 54 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-prov-s039-rollback'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WB/card-provenance'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = 'wb-teaser-prov-s039-rollback' AND l.table_name = 'unified_sites'
   AND l.column_name IN ('raw_data')
   AND EXISTS (SELECT 1 FROM unified_sites u
                WHERE u.id::text = l.row_pk AND CASE l.column_name
                WHEN 'raw_data' THEN u.raw_data IS NOT DISTINCT FROM l.new_value::jsonb
                ELSE false END)
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
